Func<Orc.Game.Damage.DamageApplyView, Context, CancellationToken, Task> Handle = async (view, ctx, ct) =>
{
    var host = view.Host;
    if (host is null || !object.ReferenceEquals(view.Target, host)) { return; }

    // 强磁护盾：受到的伤害 -1（对战/效果/战斗三类伤害同一处理端；下限 0）。
    view.Amount = System.Math.Max(0, view.Amount - 1);
};

Func<Orc.Game.Commanding.UnitAttackTriggerView, Context, CancellationToken, Task> Handle = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (view.Attacker is not { } attacker || !object.ReferenceEquals(attacker.Value, host)) { return; }
    if (!view.IsCommandAttack) { return; } // 仅玩家指挥攻击（效果发起的攻击不失去）

    await host.Keywords.RevokeAsync("强磁护盾");
};
